using uint8=uint8_t;using int8=int8_t;using uint32=uint32_t;
enum TradeSlots{TRADE_SLOT_0,TRADE_SLOT_1,TRADE_SLOT_2,TRADE_SLOT_3,TRADE_SLOT_4,TRADE_SLOT_5,TRADE_SLOT_NONTRADED,TRADE_SLOT_COUNT};
constexpr int TRADE_SLOT_TRADED_COUNT=6;
enum{CMSG_INITIATE_TRADE,CMSG_BEGIN_TRADE,CMSG_SET_TRADE_GOLD,CMSG_SET_TRADE_ITEM,CMSG_CLEAR_TRADE_ITEM,TRADE_STATUS_OPEN_WINDOW,TRADE_STATUS_TRADE_CANCELED};
struct ObjectGuid{uint64_t value=0;ObjectGuid()=default;ObjectGuid(uint64_t x):value(x){}bool IsPlayer()const{return value>0&&value<10000;}bool operator==(ObjectGuid x)const{return value==x.value;}};
struct WorldPacket{std::vector<uint64_t>data;size_t pos=0;WorldPacket(int=0,int=0){}WorldPacket&operator<<(ObjectGuid x){data.push_back(x.value);return *this;}template<class T>WorldPacket&operator<<(T x){data.push_back(uint64_t(x));return *this;}WorldPacket&operator>>(ObjectGuid&x){x.value=data.at(pos++);return *this;}template<class T>WorldPacket&operator>>(T&x){x=T(data.at(pos++));return *this;}};
struct Player;struct WorldSession;struct TradeData;struct Group{};
extern std::vector<std::string>events;
struct Item{Player*owner=nullptr;uint32 id=1;bool transferable=true,soulbound=false,equipped=true;uint8 bag=0,slot=1;ObjectGuid guid{10001};bool CanBeTraded()const{return transferable;}bool IsInTrade()const;bool IsSoulBound()const{return soulbound;}bool CanTradeSoulBoundToPlayer(ObjectGuid)const{return false;}uint32 GetOriginMapId()const{return 0;}ObjectGuid GetObjectGuid()const{return guid;}uint8 GetBagSlot()const{return bag;}uint8 GetSlot()const{return slot;}};
struct Player{ObjectGuid guid;union{TradeData*trade=nullptr;TradeData*m_trade;};WorldSession*session=nullptr;Group*group=nullptr;std::vector<Item*>inventory;uint32 money=2000;Player*GetTrader();TradeData*GetTradeData(){return trade;}WorldSession*GetSession(){return session;}ObjectGuid GetObjectGuid()const{return guid;}uint32 GetMapId()const{return 0;}Group*GetGroup()const{return group;}uint32 GetMoney()const{return money;}bool IsBankPos(uint8 bag,uint8)const{return bag==255;}Item*GetItemByPos(uint8 b,uint8 s){for(auto*i:inventory)if(i->bag==b&&i->slot==s)return i;return nullptr;}};
struct TradeData{Player*player;Player*trader;std::array<Item*,TRADE_SLOT_COUNT>items{};std::array<ObjectGuid,TRADE_SLOT_COUNT>m_items{};bool accepted=true;uint32 spell=123,money=0;int updates=0,spellResets=0;TradeData(Player*p,Player*t):player(p),trader(t){}Player*GetTrader(){return trader;}TradeData*GetTraderData(){return trader->trade;}Item*GetItem(TradeSlots s){for(auto*i:player->inventory)if(i->GetObjectGuid()==m_items[s])return i;return nullptr;}bool HasItem(ObjectGuid g){return std::any_of(m_items.begin(),m_items.end(),[&](ObjectGuid x){return x==g;});}void SetItem(TradeSlots,Item*);void SetAccepted(bool x){accepted=x;}void SetLastModificationTime(time_t){}void SetMoney(uint32 x){money=x;}void Update(){++updates;events.push_back("item-update");}void SetSpell(uint32 x){spell=x;++spellResets;}};
Player*Player::GetTrader(){return trade?trade->trader:nullptr;}
bool Item::IsInTrade()const{return owner&&owner->trade&&owner->trade->HasItem(guid);}
struct ObjectMgr{std::map<uint64_t,Player*>players;Player*GetPlayer(ObjectGuid g){return players.count(g.value)?players[g.value]:nullptr;}}sObjectMgr;
std::vector<std::string>events;
struct WorldSession{Player*_player=nullptr;bool denied=false,removeInventory=false;int initCalls=0,beginCalls=0,setCalls=0,clearCalls=0,cancellations=0;bool IsFingerprintBanned(){++beginCalls;return false;}Player*GetPlayer(){return _player;}void SendTradeStatus(int s){events.push_back(s==TRADE_STATUS_OPEN_WINDOW?"open":"cancel");if(s==TRADE_STATUS_TRADE_CANCELED)++cancellations;}void HandleInitiateTradeOpcode(WorldPacket&p){++initCalls;ObjectGuid g;p>>g;Player*other=sObjectMgr.GetPlayer(g);events.push_back("init");if(denied||!other||_player->trade||other->trade)return;_player->trade=new TradeData(_player,other);other->trade=new TradeData(other,_player);if(removeInventory)_player->inventory.clear();}void HandleBeginTradeOpcode(WorldPacket&);void HandleSetTradeItemOpcode(WorldPacket&);void HandleClearTradeItemOpcode(WorldPacket&);void HandleSetTradeGoldOpcode(WorldPacket&);};
#include "native-set-item.inc"
#include "native-handlers.inc"
enum class IterateItemsMask:uint8{ITERATE_ITEMS_IN_EQUIP=1,ITERATE_ITEMS_IN_BAGS=2};
struct ChatHelper{Player*explicitPlayer=nullptr;std::list<ObjectGuid>parseGameobjects(std::string const&){return explicitPlayer?std::list<ObjectGuid>{explicitPlayer->guid}:std::list<ObjectGuid>{};}uint32 parseMoney(std::string const&s){return s.find("10s")!=std::string::npos?1000:0;}};
struct PlayerbotAI{Player*bot;std::list<Item*>InventoryParseItems(std::string const&s,IterateItemsMask){std::list<Item*>result;if(s.find("[item]")!=std::string::npos)for(auto*i:bot->inventory)if(i->id==1)result.push_back(i);return result;}};
struct Event{std::string source,param;Player*owner;std::string getSource(){return source;}std::string getParam(){return param;}Player*getOwner(){return owner;}};
struct TradeAction{Player*bot;Player*master;PlayerbotAI*ai;ChatHelper*chat;Player*GetMaster(){return master;}bool Execute(Event&);bool TradeItem(Item const&,int8);};
#include "native-trade.inc"
void check(bool b,char const*s){if(!b)throw std::runtime_error(s);}
struct Fixture{Group group;Player bot{{1}},master{{2}},other{{3}};WorldSession bs{&bot},ms{&master},os{&other};Item item,second,third;ChatHelper chat;PlayerbotAI ai{&bot};TradeAction action{&bot,&master,&ai,&chat};Fixture(){events.clear();sObjectMgr.players={{1,&bot},{2,&master},{3,&other}};bot.session=&bs;master.session=&ms;other.session=&os;bot.group=master.group=other.group=&group;item.owner=second.owner=third.owner=&bot;second.guid={10002};second.slot=2;third.guid={10003};third.slot=3;bot.inventory={&item};}~Fixture(){delete bot.trade;delete master.trade;delete other.trade;}void open(){bot.trade=new TradeData(&bot,&master);master.trade=new TradeData(&master,&bot);}bool command(std::string source="nt",std::string text="[item]"){Event e{source,text,&master};return action.Execute(e);}Item*nontrade(){return bot.trade?bot.trade->GetItem(TRADE_SLOT_NONTRADED):nullptr;}};
void first(){Fixture f;check(f.command(),"first nt should succeed");check(f.nontrade()==&f.item,"one nt opens and offers item");check(events==std::vector<std::string>({"init","open","open","item-update"}),"native open precedes item update");check(!f.bot.trade->accepted&&!f.master.trade->accepted,"native item mutation resets both acceptance flags");check(f.master.trade->spell==0&&f.bot.trade->spell==0,"native enchanting state is reset");check(!f.bs.cancellations&&f.item.equipped&&f.item.owner==&f.bot,"no duplicate rejection, unequip or ownership transfer");}
void explicitNt(){Fixture f;f.open();f.bot.inventory={&f.item,&f.second};check(f.command("nt","[item] 2"),"explicit nt succeeds");check(f.nontrade()==&f.item&&!f.bot.trade->GetItem(TRADE_SLOT_0),"nt forces one transferable item into non-traded slot");check(!f.bs.cancellations,"native duplicate check must not reject a prefilled item");check(f.bot.trade->updates==1,"native item update exactly once");}
void soulbound(){Fixture f;f.open();f.item.transferable=false;f.item.soulbound=true;check(f.command()&&f.nontrade()==&f.item,"soulbound equipped item may be offered without transfer");check(f.item.equipped&&f.item.owner==&f.bot,"native equipped ownership preserved");check(!f.bs.cancellations,"native non-traded placement must not see a prefilled duplicate");}
void repeat(){Fixture f;f.open();f.command();int updates=f.bot.trade->updates;check(f.command()&&f.nontrade()==&f.item,"same nt is idempotent");check(f.bot.trade->updates==updates&&!f.bs.cancellations,"repeat does not submit duplicate native set");}
void occupied(){Fixture f;f.open();f.bot.inventory={&f.second};f.second.owner=&f.bot;f.second.id=2;f.bot.trade->SetItem(TRADE_SLOT_NONTRADED,&f.second);f.bot.inventory={&f.item,&f.second};check(!f.command(),"occupied different item must be refused");check(f.nontrade()==&f.second,"existing non-traded offer retained");}
void denied(){Fixture f;f.bs.denied=true;check(!f.command(),"denied native initiation must fail");check(!f.bot.trade&&events==std::vector<std::string>({"init"}),"native failure never forces a window or item");}
void partner(){Fixture f;f.bot.trade=new TradeData(&f.bot,&f.other);f.other.trade=new TradeData(&f.other,&f.bot);check(!f.command()&&!f.nontrade(),"master cannot populate another partner's trade");Fixture busy;busy.master.trade=new TradeData(&busy.master,&busy.other);check(!busy.command()&&!busy.bot.trade,"busy requested partner is unchanged");Fixture target;target.chat.explicitPlayer=&target.other;check(target.command()&&target.bot.GetTrader()==&target.other,"explicit player link keeps intended partner");}
void nativeReject(){Fixture f;f.open();f.item.bag=255;check(!f.command()&&!f.nontrade()&&f.bs.cancellations==1,"native bank restriction is not bypassed");Fixture dup;dup.open();dup.bot.trade->SetItem(TRADE_SLOT_0,&dup.item);check(!dup.command()&&!dup.nontrade(),"item in another trade slot cannot be duplicated");}
void normal(){Fixture f;f.open();f.bot.inventory={&f.item,&f.second,&f.third};check(f.command("t","[item] 2"),"normal counted trade succeeds");check(f.bot.trade->GetItem(TRADE_SLOT_0)==&f.item&&f.bot.trade->GetItem(TRADE_SLOT_1)==&f.second&&!f.bot.trade->GetItem(TRADE_SLOT_2)&&!f.nontrade(),"ordinary t retains slots and count");Fixture bound;bound.open();bound.item.transferable=false;check(bound.command("t")&&bound.nontrade()==&bound.item,"ordinary non-transferable fallback retained");}
void money(){Fixture f;check(f.command("t","10s")&&f.bot.trade->money==1000,"native money-only trade retained");Fixture nt;nt.open();check(nt.command("nt","[item] 10s")&&!nt.bot.trade->money,"non-traded item request cannot offer money");}
void missing(){Fixture f;check(!f.command("nt","[missing]")&&!f.bot.trade&&!f.bs.initCalls,"unmatched nt does not initiate empty trade");}
void scriptChange(){Fixture f;f.bs.removeInventory=true;check(!f.command()&&f.bot.trade&&!f.nontrade(),"inventory is resolved again after native initiation hooks");}
void cancelled(){Fixture f;check(f.command()&&f.nontrade()==&f.item,"first offer succeeds before cancellation");delete f.bot.trade;delete f.master.trade;f.bot.trade=f.master.trade=nullptr;check(!f.item.IsInTrade(),"cancelled trade retains item outside all slots");check(f.command()&&f.nontrade()==&f.item&&f.bs.initCalls==2,"a new explicit request starts a fresh native trade");}
void legacy(){Fixture f;check(f.command()&&f.bot.trade&&!f.nontrade()&&!f.bs.beginCalls,"other cores retain existing initiate/acknowledgement flow");check(f.command()&&f.nontrade()==&f.item,"subsequent request uses native non-traded placement");}
int main(int argc,char**argv){try{std::string s=argc>1?argv[1]:"first_nt";if(s=="first_nt")first();else if(s=="explicit_nt")explicitNt();else if(s=="soulbound")soulbound();else if(s=="repeat")repeat();else if(s=="occupied")occupied();else if(s=="denied")denied();else if(s=="partner")partner();else if(s=="native_reject")nativeReject();else if(s=="normal")normal();else if(s=="money")money();else if(s=="missing")missing();else if(s=="script_change")scriptChange();else if(s=="cancelled")cancelled();else legacy();std::cout<<"PASS "<<s<<'\n';}catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
